  "M0 0 C6.01736204 4.62959404 10.54710186 8.97650689 12.1171875 16.62890625 C12.76978465 22.1162372 12.64195863 26.1171992 9.1171875 30.62890625 C8.1171875 31.62890625 8.1171875 31.62890625 5.4765625 31.8984375 C1.40254226 31.57156843 -1.05529301 30.27109167 -4.6328125 28.31640625 C-20.20622883 20.20397957 -36.0121107 19.34542513 -52.8828125 24.62890625 C-56.40038462 26.23192221 -59.69821767 28.16280676 -62.98046875 30.203125 C-66.26890956 31.81857708 -68.26560686 32.09695536 -71.8828125 31.62890625 C-74.94753982 28.48352821 -76.16191424 25.6911555 -76.4453125 21.37890625 C-76.02927033 13.64312208 -72.26359091 7.57506713 -66.7578125 2.31640625 C-48.95077704 -12.34995407 -19.05537159 -12.79982031 0 0 Z";

const TEAL_TX = 15;
const TEAL_TY = 9;
const PILLAR_TX = 114.057;
const PILLAR_TY = 78.757;
const ARC_TX = 157.883;
const ARC_TY = 20.371;

const VIEW_W = 248;
const VIEW_H = 288;

interface LogoLoaderProps {
  onComplete?: () => void;
  duration?: number;
}

export function LogoLoader({ onComplete, duration = 2400 }: LogoLoaderProps) {
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const start = performance.now();
    let raf = 0;
    const tick = (t: number) => {
      const p = Math.min(1, (t - start) / duration);
      setProgress(p);
      if (p < 1) {
        raf = requestAnimationFrame(tick);
      } else {
        onComplete?.();
      }
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [duration, onComplete]);

  // Water level travels from below the logo up past the top.
  const level = VIEW_H + 12 - progress * (VIEW_H + 24);
  const waveAmp = 5;

  return (
    <div className="fixed inset-0 z-[200] grid place-items-center bg-background animate-fade-in">
      <div className="flex flex-col items-center gap-6">
        <svg
          viewBox={`0 0 ${VIEW_W} ${VIEW_H}`}
          className="w-40 sm:w-48 h-auto drop-shadow-[0_8px_30px_hsl(174_62%_47%_/_0.25)]"
          aria-label="Loading"
          role="img"
        >
          <defs>
            {/* Clip = full logo silhouette so the water only fills the logo */}
            <clipPath id="logo-water-clip" clipPathUnits="userSpaceOnUse">
              <path transform={`translate(${TEAL_TX} ${TEAL_TY})`} d={TEAL_D} />
              <path transform={`translate(${PILLAR_TX} ${PILLAR_TY})`} d={PILLAR_D} />
              <path transform={`translate(${ARC_TX} ${ARC_TY})`} d={ARC_D} />
            </clipPath>

            <linearGradient id="logo-water-grad" x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%" stopColor="#02C8B3" />
              <stop offset="55%" stopColor="#368A97" />
              <stop offset="100%" stopColor="#E8742B" />
            </linearGradient>
          </defs>

          {/* Empty logo outline */}
          <g
            fill="none"
            stroke="hsl(180 28% 33% / 0.22)"
            strokeWidth="1.4"
            strokeLinejoin="round"
          >
            <path transform={`translate(${TEAL_TX} ${TEAL_TY})`} d={TEAL_D} />
            <path transform={`translate(${PILLAR_TX} ${PILLAR_TY})`} d={PILLAR_D} />
            <path transform={`translate(${ARC_TX} ${ARC_TY})`} d={ARC_D} />
          </g>

          {/* Water fill, clipped to the logo silhouette */}
          <g clipPath="url(#logo-water-clip)">
            {/* Solid fill below the wave */}
            <rect
              x="-20"
              y={level + waveAmp}
              width={VIEW_W + 40}
              height={VIEW_H + 60}
              fill="url(#logo-water-grad)"
            />

            {/* Animated wave top — translated horizontally for motion */}
            <g className="logo-water-wave">
              <path
                fill="url(#logo-water-grad)"
                d={
                  `M-${VIEW_W} ${level} ` +
                  `Q-${VIEW_W * 0.75} ${level - waveAmp} -${VIEW_W * 0.5} ${level} ` +
                  `T0 ${level} T${VIEW_W * 0.5} ${level} T${VIEW_W} ${level} ` +
                  `T${VIEW_W * 1.5} ${level} T${VIEW_W * 2} ${level} ` +
                  `L${VIEW_W * 2} ${level + waveAmp + 2} L-${VIEW_W} ${level + waveAmp + 2} Z`
                }
              />
            </g>

            {/* Soft highlight along the waterline */}
            <rect
              x="-20"
              y={level - 0.6}
              width={VIEW_W + 40}
              height="1.4"
              fill="white"
              opacity="0.45"
            />
          </g>
        </svg>

        <div className="flex flex-col items-center gap-2">
          <div className="h-1 w-40 rounded-full bg-muted overflow-hidden">
            <div
              className="h-full rounded-full"
              style={{
                width: `${progress * 100}%`,
                background:
                  "linear-gradient(90deg, hsl(174 62% 47%), hsl(20 79% 54%))",
                transition: "width 80ms linear",
              }}
            />
          </div>
          <p className="text-xs uppercase tracking-[0.3em] text-muted-foreground">
            Loading
          </p>
        </div>
      </div>

      <style>{`
        .logo-water-wave {
          animation: logo-water-flow 2.4s linear infinite;
          transform-box: fill-box;
        }
        @keyframes logo-water-flow {
          0%   { transform: translateX(0); }
          100% { transform: translateX(${VIEW_W * 0.5}px); }
        }
        @media (prefers-reduced-motion: reduce) {
          .logo-water-wave { animation: none; }
        }
      `}</style>
    </div>
  );
}
